'use strict';
function sequenceArtifacts(artifacts) {
  return artifacts
    .slice()
    .sort((a, b) => (a.priority || 0) - (b.priority || 0) || a.name.localeCompare(b.name));
}
module.exports = { sequenceArtifacts };

'use strict';
function countCritical(findings) {
  return findings.filter((f) => f.severity === 'critical').length;
}
function passesGate(findings, maxCritical) {
  return countCritical(findings) <= (maxCritical || 0);
}
module.exports = { countCritical, passesGate };

'use strict';
function findConflicts(resources) {
  const seen = {};
  const conflicts = [];
  for (const r of resources) {
    if (seen[r.id]) conflicts.push(r.id);
    else seen[r.id] = true;
  }
  return conflicts;
}
module.exports = { findConflicts };

'use strict';
function createDeployment(config) {
  const state = { phase: 'pending', version: config.version, canaries: [] };
  return {
    promote(target) {
      if (state.phase !== 'pending') throw new Error('already promoted');
      state.phase = 'canary';
      state.canaries.push({ target, deployedAt: Date.now() });
      return state;
    },
    fullRollout() {
      if (state.phase !== 'canary') throw new Error('must promote first');
      state.phase = 'full';
      state.rolloutAt = Date.now();
      return state;
    },
    getStatus() { return { ...state }; }
  };
}
module.exports = { createDeployment };
